<script setup lang="ts">
import {useCardText} from '../text'
import {displayName} from '../format'
import type {ReportSummary} from './types'
defineProps<{rows:ReportSummary[];expiry:boolean;byCustomer?:boolean}>();const {locale}=useCardText(),x=(zh:string,en:string)=>locale.value.startsWith('en')?en:zh
const unit=(v:string)=>v==='card'?x('张','cards'):v==='stamp'?x('次集次','stamps'):v
</script>
<template><div class="cards-table-scroll"><table class="cards-data-table"><thead><tr><th>{{byCustomer?x('顾客 / 单位','Customer / unit'):x('卡方案 / 单位','Plan / unit')}}</th><th>{{x('笔数','Entries')}}</th><template v-if="expiry"><th>{{x('到期未用','Unused expiry')}}</th></template><template v-else><th>{{x('核销 / 冲正 / 净核销','Redeemed / reversed / net')}}</th><th>{{x('集次 / 撤回 / 净集次','Stamps / reversed / net')}}</th><th>{{x('发放 / 退卡 / 撤销奖励','Granted / returned / revoked')}}</th></template></tr></thead><tbody><tr v-for="row in rows" :key="(row.groupId||row.planId||'unknown')+row.unit"><td>{{displayName(row,locale)||x('顾客资料不可用','Customer details unavailable')}}<small v-if="row.groupPhone">{{row.groupPhone}}</small><small>{{unit(row.unit)}}</small></td><td>{{row.count}}</td><td v-if="expiry">{{row.expired}} {{unit(row.unit)}}</td><template v-else><td><small>{{x('核销','Redeemed')}} {{row.redeemed}} · {{x('冲正','Reversed')}} {{row.redeemReversed}}</small><strong>{{x('净核销','Net')}} {{row.redeemed-row.redeemReversed}}</strong></td><td><small>{{x('集次','Stamps')}} {{row.stamps}} · {{x('撤回','Reversed')}} {{row.stampReversed}}</small><strong>{{x('净集次','Net')}} {{row.stamps-row.stampReversed}}</strong></td><td><small>{{x('发放','Granted')}} {{row.granted}} · {{x('退卡','Returned')}} {{row.returned??0}} · {{x('撤销','Revoked')}} {{row.revoked}}</small><strong>{{x('净发放','Net')}} {{row.granted-(row.returned??0)-row.revoked}}</strong></td></template></tr></tbody></table></div></template>
